--- a/components/adblock/android/java/src/org/chromium/components/adblock/ShieldsSiteState.java
+++ b/components/adblock/android/java/src/org/chromium/components/adblock/ShieldsSiteState.java
@@ -41,8 +41,13 @@
         String canonical = canonicalHost(host);
         if (canonical == null) return matching;
         for (String entry : domains) {
-            String domain = canonicalHost(entry);
-            if (domain != null && (canonical.equals(domain) || canonical.endsWith("." + domain))) {
+            // Only match entries that are already ASCII-compatible to avoid false claims
+            // for Unicode entries that DomainOption would reject.
+            boolean isAscii = true;
+            for (int i = 0; i < entry.length(); i++) {
+                if (entry.charAt(i) > 127) { isAscii = false; break; }
+            }
+            if (isAscii) {
+                String domain = canonicalHost(entry);
+                if (domain != null && (canonical.equals(domain) || canonical.endsWith("." + domain))) {
+                    matching.add(entry);
+                }
+            }
         }
         return matching;
     }
